create extension if not exists pgcrypto with schema extensions;
create or replace function public.generate_invite_code() returns text language sql volatile set search_path=pg_catalog,public as $$ select upper(substr(encode(extensions.gen_random_bytes(6),'hex'),1,8)); $$;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,name text not null check(char_length(trim(name)) between 1 and 80),badge text,created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$ declare display_name text; begin display_name:=coalesce(nullif(trim(new.raw_user_meta_data->>'name'),''),split_part(new.email,'@',1),'Estudante'); insert into public.profiles(id,name) values(new.id,left(display_name,80)) on conflict(id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create table public.daily_tasks (id bigint generated always as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,title text not null check(char_length(trim(title)) between 1 and 160),category text not null default 'geral',task_date date not null default(timezone('America/Sao_Paulo',now()))::date,done boolean not null default false,done_at timestamptz,created_at timestamptz not null default now()); create index daily_tasks_user_date_idx on public.daily_tasks(user_id,task_date);
create table public.goals (id bigint generated always as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,category text not null default 'geral',title text not null check(char_length(trim(title)) between 1 and 160),due_date date,progress numeric(5,4) not null default 0 check(progress between 0 and 1),icon text,completed_at timestamptz,created_at timestamptz not null default now()); create index goals_user_completed_idx on public.goals(user_id,completed_at);
create table public.check_ins (id bigint generated always as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,check_date date not null,minutes integer not null default 0 check(minutes between 0 and 1440),created_at timestamptz not null default now(),unique(user_id,check_date));
create table public.points_events (id bigint generated always as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,source text not null check(source in('check_in','task_done','goal_done','streak_bonus')),ref_id bigint not null,points integer not null check(points>0),event_date date not null default(timezone('America/Sao_Paulo',now()))::date,created_at timestamptz not null default now(),unique(user_id,source,ref_id)); create index points_events_user_date_idx on public.points_events(user_id,event_date);
create table public.squads (id bigint generated always as identity primary key,name text not null check(char_length(trim(name)) between 1 and 100),subtitle text not null default '',invite_code text not null unique,season_ends_at timestamptz,created_by uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now());
create or replace function public.ensure_invite_code() returns trigger language plpgsql set search_path=pg_catalog,public as $$ begin if new.invite_code is null or btrim(new.invite_code)='' then loop new.invite_code:=public.generate_invite_code(); exit when not exists(select 1 from public.squads where invite_code=new.invite_code); end loop; end if; new.invite_code:=upper(new.invite_code); return new; end; $$; create trigger squads_invite_code before insert on public.squads for each row execute function public.ensure_invite_code();
create table public.squad_members (squad_id bigint not null references public.squads(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),primary key(squad_id,user_id)); create index squad_members_user_idx on public.squad_members(user_id);
create table public.squad_activity (id bigint generated always as identity primary key,squad_id bigint not null references public.squads(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,action text not null check(char_length(trim(action)) between 1 and 80),payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()); create index squad_activity_squad_date_idx on public.squad_activity(squad_id,created_at desc);
